contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send and a dummy timestamp-influencing uint (unused here)
    // but must ensure we can send Ether from this contract
    function run(uint dummy, uint amount) public payable {
        require(address(this).balance >= amount);
        // Read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Make the call that may revert. Must be top-level.
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule: if call reverted then nothing observable on c changed; if it did not revert and amount == 10 ether:
        //   - pastBlockTime must be strictly > beforePast (since require(block.timestamp > pastBlockTime) and then updated)
        //   - if block.number % 15 == 0 then contract paid out its entire balance (so afterBal == 0)
        //   - otherwise contract balance increased by exactly amount
        // We cannot refer to block.timestamp inside assert for a strict inequality beyond beforePast, so we assert the observable relations.
        assert(
            // If reverted: past and balance unchanged
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            ||
            // If not reverted: require amount == 10 ether and past advanced and balances follow payout rule
            (!reverted && amount == 10 ether && afterPast > beforePast && (
                (block.number % 15 == 0 && afterBal == 0)
                ||
                (block.number % 15 != 0 && afterBal == beforeBal + amount)
            ))
        );
    }

    // allow receiving refunded Ether if any
    receive() external payable {}
}

