contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll send ETH to c by calling its fallback via a plain call with value.
    // Parameters: amount to send (must be 10 ether to avoid immediate revert), a synthetic blockTime increment
    // and a flag we don't use; primary input is the amount and a dummy uint to make inputs symbolic.
    function run(uint amount, uint dummy) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");
        // Read observable before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // perform the state-changing call: trigger fallback by sending ETH
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule:
        // - If the call reverted then amount != 10 ether or block.timestamp <= beforePast.
        // - If it did not revert then afterPast >= beforePast (specifically > if amount==10 ether and it passed require)
        //   and either contract balance decreased to 0 when block.number%15==0 (payout), or otherwise contract balance >= beforeBal (it accepted Ether).
        assert(
            reverted
            ? (amount != 10 ether || block.timestamp <= beforePast)
            : (
                // successful call implies amount == 10 ether
                amount == 10 ether
                // pastBlockTime must have been updated to a timestamp >= beforePast
                && afterPast >= beforePast
                // balance behavior: if payout block then c balance becomes either 0 (it paid out) or unchanged if nothing to pay
                && (
                    (block.number % 15 == 0
                        ? (afterBal == 0 || afterBal >= beforeBal)
                        : afterBal >= beforeBal)
                )
            )
        );
    }

    receive() external payable {}
}

