    // amount: Ether to send to c (we will require it equals 10 ether to exercise the fallback path),
    // advanceTimestampGreater: a boolean indicating expectation whether the current block.timestamp should be greater than previous pastBlockTime
    // We cannot change block.timestamp here, but we can observe behavior: if the call succeeds, pastBlockTime must equal the getter value and be >= previous one and strictly greater than previous; if it reverts, reverted flag true.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Read pre-state
        uint beforeTime = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
