        assert(
            (reverted && afterTime == beforeTime && afterBal == beforeBal)
            || (
                !reverted
                && afterTime > beforeTime
                && afterTime == c.pastBlockTime()
                && (afterBal == 0 || afterBal == beforeBal + amount)
